const envelope = $input.first().json;
const status = envelope.result || envelope;
const candidates = (status.email_contacts || []).filter(c => c.verification === 'VERIFIED_HIGH');
return candidates.map(c => {
  const why = (c.why || '').toLowerCase();
  let opportunity_type = 'manual-review';
  if (why.includes('calculator') || why.includes('quote')) opportunity_type = 'quote-or-calculator';
  else if (why.includes('booking')) opportunity_type = 'booking-automation';
  else if (why.includes('form')) opportunity_type = 'lead-flow-improvement';
  return { json: { ...c, opportunity_type, next_action: 'HUMAN_REVIEW' } };
});
